const fs = require("fs");
const path = require("path");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  if (typeof tw.__unstable__loadDesignSystem !== "function") broken("__unstable__loadDesignSystem is missing");
  const dir = path.dirname(require.resolve("tailwindcss/package.json"));
  const css = fs.readFileSync(path.join(dir, "index.css"), "utf8");
  const ds = await tw.__unstable__loadDesignSystem(css, { base: dir });
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const opts = { collapse: true, logicalToPhysical: true };
  const ctl = ds.canonicalizeCandidates(["mt-1", "mb-1"], opts);
  if (JSON.stringify(ctl) !== JSON.stringify(["my-1"])) broken("control mt-1 mb-1 gave " + JSON.stringify(ctl));
  const got = ds.canonicalizeCandidates(["scroll-mt-1", "scroll-mb-1"], opts);
  if (JSON.stringify(got) === JSON.stringify(["scroll-my-1"])) {
    console.log("OK: scroll-mt-1 scroll-mb-1 collapse into scroll-my-1");
    process.exit(0);
  }
  if (got.length === 2 && got.includes("scroll-mt-1") && got.includes("scroll-mb-1")) symptom("scroll-mt-1 scroll-mb-1 are not collapsed into scroll-my-1");
  broken("unexpected result " + JSON.stringify(got));
})().catch((e) => broken(String((e && e.stack) || e)));

